// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LineAxis {
    function balanceOf(address owner) external view returns (uint);
    function approve(address spender, uint256 value) external;
    function frozen() external view returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond what's in the test template
        // The test template already sets up TARGET and attacker
        // We just need to ensure we have some token balance
        LineAxis token = LineAxis(TARGET);

        // Check if contract is frozen (precondition requires frozen == false)
        require(!token.frozen(), "Contract is frozen, cannot proceed");

        // Get our current balance
        uint256 attackerBalance = token.balanceOf(attacker);

        // If we have zero balance, we need to get some tokens
        // Since we can't mint (only owner can), we need to get tokens from somewhere
        // Let's check if the deployer/owner has tokens we can transfer
        address owner = token.owner();

        // If owner has tokens, we can try to get some via transferFrom if we have allowance
        // But for simplicity, let's assume we already have some balance from test setup
        // We'll just verify we have balance > 0
        require(attackerBalance > 0, "Attacker must have token balance");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        LineAxis token = LineAxis(TARGET);

        // Get our current balance
        uint256 attackerBalance = token.balanceOf(attacker);

        // Try to approve an amount greater than our balance
        // This should revert due to the incorrect implementation
        uint256 approvalAmount = attackerBalance + 1;
        address spender = address(0x123); // Arbitrary spender address

        // The oracle expects this call to fail (success == false)
        // We'll use try-catch to demonstrate the revert
        bool success;
        bytes memory returnData;

        (success, returnData) = address(token).call(
            abi.encodeWithSignature("approve(address,uint256)", spender, approvalAmount)
        );

        // Verify the call failed (reverted)
        require(!success, "approve() should have reverted but didn't");

        // Optional: Check the revert reason contains "Out of value"
        // if (returnData.length > 0) {
        //     // Parse revert reason
        // }
        assertEq(success, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
